const iconName = { 'id-card':'idCard','plane':'plane','car-front':'car','wallet':'wallet','graduation-cap':'cap','landmark':'landmark'};
function icon(name, cls='') {return `<svg class="ui-icon ${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${glyphs[iconName[name]||name]||glyphs.info}</svg>`;}
function esc(value='') {return String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function button(label, href, style='primary', suffix='arrow') {return `<a class="button button-${style}" href="${href}">${label} ${suffix ? icon(suffix):''}</a>`;}
function pillar(ico, title, text) {return `<div class="feature-card"><span class="icon-tile">${icon(ico)}</span><h3>${title}</h3><p>${text}</p></div>`;}
function guideCard(guide) {return `<a class="service-card" href="${secureServiceLink(guide.id)}"><div class="flex-between"><span class="icon-tile ${guide.accent==='orange'?'orange':''}">${icon(guide.icon)}</span><span class="pill subtle">${guide.minutes} guide</span></div><h3>${esc(guide.name)}</h3><p>${esc(guide.blurb)}</p>${guide.institutions?`<div class="brand-chips">${guide.institutions.map(name=>`<span>${esc(name)}</span>`).join('')}</div>`:''}<div class="service-foot"><span>${esc(guide.category)}</span><span class="mini-action" aria-hidden="true">${icon('arrowUp')}</span></div></a>`;}
function categoryTile(category) {const count=guides.filter(guide=>guide.category===category.name).length;const institutions=category.slug==='education'?'UNISA · UJ · UP · Wits · TUT':category.slug==='banking'?'Capitec · FNB · Absa · Nedbank · Standard Bank':'';return `<a class="category-tile" href="category.html?category=${category.slug}"><img src="assets/images/${category.image}" alt="${category.slug==='government'?'Woman preparing to visit a civic services office':category.slug==='banking'?'Man using mobile banking at a café':'Students researching university applications together'}" loading="lazy" decoding="async"><span class="category-tile-shade"></span><span class="category-tile-content"><span class="category-kicker">${count} practical ${count===1?'guide':'guides'}</span><strong>${esc(category.name)}</strong><span>${esc(category.description)}</span>${institutions?`<span class="category-tile-institutions">${institutions}</span>`:''}</span><span class="category-tile-action" aria-hidden="true">${icon('arrowUp')}</span></a>`;}
function sourceLinks(guide) {return `<p class="source-date">Last reviewed: ${reviewedAt}</p><ul class="source-list">${guide.sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('external')}</a></li>`).join('')}</ul>`;}

function header(){
  const active = (key)=>page===key?'active':'';
  return `<a class="skip-link" href="#app">Skip to main content</a><header class="site-header"><div class="site-header-inner container"><a href="index.html" class="brand" aria-label="OneTrip — home"><span class="brand-mark">${brandSvg}</span><span>onetrip</span></a><nav id="main-nav" class="nav-links" aria-label="Main navigation"><a class="${active('services')}" href="services.html">Explore services</a><a class="${active('how')}" href="how-it-works.html">How it works</a><a class="${active('help')}" href="help.html">Help</a><a class="button button-primary mobile-only-cta" href="prepare.html">Prepare my visit ${icon('arrow')}</a></nav><a class="button button-primary nav-cta" href="prepare.html">Prepare my visit ${icon('arrow')}</a><button class="mobile-toggle" id="menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="Open navigation">${icon('menu')}</button></div></header>`;
}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div><a href="index.html" class="brand"><span class="brand-mark">${brandSvg}</span><span>onetrip</span></a><p>Go prepared. Get it done. Practical preparation for everyday South Africans.</p><span class="pill dark">Independent guidance</span></div><div class="footer-links"><h4>Explore</h4><a href="services.html">All services</a><a href="prepare.html">Prepare my visit</a><a href="how-it-works.html">How it works</a></div><div class="footer-links"><h4>Support</h4><a href="help.html">Help & FAQs</a><a href="contact.html">Contact & feedback</a><a href="contact.html?topic=correction">Report incorrect info</a></div><div class="footer-links"><h4>OneTrip</h4><a href="about.html">About us</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms & conditions</a></div></div><div class="footer-base"><span>© ${new Date().getFullYear()} OneTrip. Independent service-preparation information.</span><span>Not affiliated with the institutions listed.</span></div></div></footer>`;}

function home(){return `
<section class="hero"><div class="container hero-grid"><div class="hero-text"><span class="hero-badge">${icon('compass')} Your smarter way to get things done</span><h1 class="display">One less trip.<span class="hero-strong">A lot less stress.</span></h1><p class="lead">Know what to do before you go. OneTrip helps you prepare for everyday appointments, get the right documents ready and avoid unnecessary journeys.</p><div class="button-row">${button('Prepare my visit','prepare.html','primary')}${button('Explore services','services.html','ghost','')}</div><div class="hero-mini"><span>${icon('checkCircle')} Free to use</span><span>${icon('checkCircle')} No account needed</span><span>${icon('checkCircle')} Made for South Africans</span></div></div>
<div class="hero-art" aria-label="Illustration of a completed visit checklist"><div class="art-orbit"></div><div class="art-orbit small"></div><div class="art-main"><div class="art-header"><span>Your visit checklist</span><span class="pill orange">Almost ready!</span></div><div class="art-list"><div class="art-row"><span class="art-check">${icon('check')}</span><span class="art-copy"><b>Check what you need</b><small>Requirements, made simpler</small></span></div><div class="art-row"><span class="art-check">${icon('check')}</span><span class="art-copy"><b>Get documents ready</b><small>Everything in one place</small></span></div><div class="art-row"><span class="art-check empty">${icon('circle')}</span><span class="art-copy"><b>Go with confidence</b><small>One final check</small></span></div></div><div class="art-progress"></div><div class="art-foot"><span>You're making progress</span><span>2 of 3</span></div></div><div class="art-sticker">${icon('star')} You've got this!</div><div class="art-bubble">${icon('checkCircle')} Less guessing, more doing</div></div></div></section>
<section class="section"><div class="container"><div class="section-header"><div><span class="eyebrow">Make every journey count</span><h2>What do you need to get done?</h2><p>Start with one of our carefully selected preparation guides. We’re building OneTrip service by service.</p></div><a class="button-inline" href="services.html">See all services ${icon('arrow')}</a></div><div class="grid-3">${guides.slice(0,3).map(guideCard).join('')}</div><div style="margin-top:22px" class="grid-2">${guides.slice(3).map(guideCard).join('')}</div><div class="grid-3" style="margin-top:32px">${categories.map(c=>`<a class="category-card" href="category.html?category=${c.slug}"><span class="icon-tile">${icon(c.icon)}</span><div><h3>${c.name}</h3><p>${c.description}</p></div>${icon('arrow','arrow')}</a>`).join('')}</div></div></section>
<section class="section section-tint"><div class="container"><div class="center"><span class="eyebrow">Simple by design</span><h2>Three steps. A clearer plan.</h2><p class="lead">A little preparation can make a big difference to your day.</p></div><div class="grid-3" style="margin-top:35px"><div class="step-card"><div class="step-num">01</div><h3>Choose your service</h3><p>Find the task you need help with, from a Smart ID to a university application.</p></div><div class="step-card"><div class="step-num">02</div><h3>Tell us a little</h3><p>Answer a few simple questions. No personal ID number or account required.</p></div><div class="step-card"><div class="step-num">03</div><h3>Get your checklist</h3><p>See what to prepare, whether you may need to travel and where to confirm the details.</p></div></div></div></section>
<section class="section"><div class="container grid-2" style="align-items:center;gap:65px"><div><span class="eyebrow">A different kind of guide</span><h2>Sometimes the smartest trip is the one you don't take.</h2><p class="lead">Some everyday tasks can be started or completed online. OneTrip helps you check that before spending time and money on transport.</p>${button('See how it works','how-it-works.html','ghost')}</div><div class="stack">${pillar('map','Check the route','Find out if you may be able to do the task online, or whether a visit is part of the process.')}${pillar('document','Prepare what matters','See a checklist tailored to your situation, including conditional documents and preparation tasks.')}</div></div></section>
<section class="section-tight"><div class="container"><div class="band"><div><span class="eyebrow light">Ready when you are</span><h2>Make your next visit a better one.</h2><p>No long forms. No sign-up. Just practical help before you go.</p></div>${button('Prepare my visit','prepare.html','orange')}</div></div></section>
<section class="section-tight"><div class="container"><div class="testimonial-free">${icon('shield')}<div><strong>OneTrip is an independent preparation guide.</strong><p style="margin:4px 0 0;color:#456d6b;font-size:.88rem">Requirements change. Each guide links to official sources, and you should confirm details with the institution before travelling.</p></div></div></div></section>`;}

